echo "📥 Downloading OneStopCyberShop Content"
echo "========================================"
echo ""

# Counter variables
TOTAL=0
SUCCESS=0
FAILED=0

# Function to download file
download_file() {
    local url="$1"
    local output_path="$2"
    local filename=$(basename "$output_path")

    echo "Downloading: $filename"

    if curl -f -s -L "$url" -o "$output_path" 2>/dev/null; then
        echo "  ✓ Success"
        ((SUCCESS++))
    else
        echo "  ✗ Failed"
        ((FAILED++))
    fi
    ((TOTAL++))
}

